const conversationId = $input.first().json.body.conversation_id;

if (!conversationId) {
  return {
    json: {
      success: false,
      error: 'conversation_id is required'
    }
  };
}

const supabaseUrl = 'https://ybpsseqzzhttnbpiqaws.supabase.co';
const supabaseKey = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InlicHNzZXF6emh0dG5icGlxYXdzIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NzQ3NjUzMywiZXhwIjoyMDgzMDUyNTMzfQ.mqVQjdOswUYHV0b0CNZcd2TZSaIxYkIIrUjZjVv9hTc';

try {
  // Fetch messages for this conversation
  const messages = await this.helpers.httpRequest({
    method: 'GET',
    url: `${supabaseUrl}/rest/v1/messages?conversation_id=eq.${conversationId}&order=sequence_number.asc&select=id,content,is_user,created_at,sequence_number`,
    headers: {
      'apikey': supabaseKey,
      'Authorization': `Bearer ${supabaseKey}`
    },
    json: true
  });

  // Format messages for the app
  const formattedMessages = messages.map(msg => ({
    id: msg.id,
    content: msg.content,
    is_user: msg.is_user,
    created_at: msg.created_at
  }));

  return {
    json: {
      success: true,
      messages: formattedMessages,
      conversation_id: conversationId
    }
  };
} catch (error) {
  return {
    json: {
      success: false,
      error: error.message || 'Failed to fetch messages',
      messages: []
    }
  };
}
